import{_ as i,o as l,c as a,a as o}from"./chunks/framework.Ld7uezS_.js";const m=JSON.parse('{"title":"全站小知识点深度审查与补强概览","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-knowledge-depth-audit.md","filePath":"outputs/overview-2026-08-21-knowledge-depth-audit.md","lastUpdated":1787281221000}'),d={name:"outputs/overview-2026-08-21-knowledge-depth-audit.md"};function t(r,e,c,n,s,h){return l(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="全站小知识点深度审查与补强概览" tabindex="-1">全站小知识点深度审查与补强概览 <a class="header-anchor" href="#全站小知识点深度审查与补强概览" aria-label="Permalink to &quot;全站小知识点深度审查与补强概览&quot;">​</a></h1><h2 id="一、本轮目标" tabindex="-1">一、本轮目标 <a class="header-anchor" href="#一、本轮目标" aria-label="Permalink to &quot;一、本轮目标&quot;">​</a></h2><p>针对零基础学习者反馈，对站点全部课程文件进行“知识点颗粒度”审查，重点检查是否只停留在一句定义、关键词或操作口诀，是否缺少概念、组成、原理、适用场景、差异、判断依据、异常处理、恢复和记录。</p><h2 id="二、审查范围" tabindex="-1">二、审查范围 <a class="header-anchor" href="#二、审查范围" aria-label="Permalink to &quot;二、审查范围&quot;">​</a></h2><ul><li>理论十章；</li><li><code>course-companion.md</code>、<code>glossary.md</code>；</li><li><code>skill/01-monitoring.md</code> 至 <code>skill/05-detection.md</code>；</li><li>报警系统、水系统、其他消防设施项目卡；</li><li>训练页、标准映射、知识覆盖矩阵、项目总览与项目记忆。</li></ul><p>审查采用静态章节深度盘点，并结合理论、技能、课程映射的只读交叉审查。没有把 <code>node_modules</code> 和历史 <code>outputs</code> 文档作为课程内容改写对象。</p><h2 id="三、本轮补强内容" tabindex="-1">三、本轮补强内容 <a class="header-anchor" href="#三、本轮补强内容" aria-label="Permalink to &quot;三、本轮补强内容&quot;">​</a></h2><h3 id="_1-理论知识" tabindex="-1">1. 理论知识 <a class="header-anchor" href="#_1-理论知识" aria-label="Permalink to &quot;1. 理论知识&quot;">​</a></h3><ul><li>职业道德：补充职业道德、法律法规、单位制度、操作规程和岗位授权的来源、约束对象、后果和岗位例子；增加失职、越权、误操作和合规处置辨析。</li><li>消防工作：补充政府、部门、单位、公民/员工的责任接力和“发现异常—报告—评估—维修/检测—复测—销项”的责任链。</li><li>燃烧和火灾：补充燃烧三要素与燃烧四面体的关系，以及冷却、窒息、隔离、化学抑制的对应边界。</li><li>消防设施：补充感知/触发、判断/控制、执行、反馈/供能四层理解，并区分显示、动作、反馈三类证据。</li><li>初起火灾：补充报警/报告、疏散/救人、初起灭火、复燃观察/现场保护四项任务的关系。</li><li>计算机基础：补充输入—处理—存储—输出信息链，区分文件、数据库、日志和备份，并加入报警到交接的完整例子。</li><li>法律法规与标准：补充按设计、施工验收、日常维护、故障维修和现场处置选择依据的方法，以及来源冲突时的核验顺序。</li></ul><h3 id="_2-技能与设备" tabindex="-1">2. 技能与设备 <a class="header-anchor" href="#_2-技能与设备" aria-label="Permalink to &quot;2. 技能与设备&quot;">​</a></h3><ul><li>设施操作：补充就地/远程、手动/自动、主泵/备用泵等控制方式差异，明确预期结果、异常分支和结束条件。</li><li>设施保养：补充巡查、保养、检测、维修四类工作的目的、证据和不可替代关系。</li><li>设施维修：补充故障、缺陷、误操作、临时停用、屏蔽/隔离的区别，避免把“故障消失”误判为“原因排除”。</li><li>设施检测：补充检查、测量、试验、检测、判定五个术语及证据边界。</li><li>报警系统：补充感知层、控制层、执行层、反馈层、供电通信层五层结构。</li><li>水系统：补充静压、动压、流量、最不利点、水源到末端的水力路径，明确局部证据不能外推全系统结论。</li><li>综合课程：增加统一八问学习卡，要求每个知识点回答“是什么、解决什么、组成、原理、场景、如何证明正常、异常处理、恢复记录”。</li><li>术语表：新增水力基础、检测术语、消防电梯、应急广播、消防电话、到位反馈、校准/检定状态等词条。</li></ul><h2 id="四、同步与验证" tabindex="-1">四、同步与验证 <a class="header-anchor" href="#四、同步与验证" aria-label="Permalink to &quot;四、同步与验证&quot;">​</a></h2><ul><li>已同步 <code>knowledge-coverage-matrix.md</code> 的对应缺口状态，避免已补内容仍标记为“仅一句定义”。</li><li>已更新 <code>overview.md</code> 与 <code>.workbuddy/memory/2026-08-21.md</code>。</li><li>理论题卡：T01-T39，共 39 张；无缺号、无重复。</li><li>技能题卡：S01-S49，共 49 张；无缺号、无重复。</li><li>排除 <code>node_modules</code> 和 <code>outputs</code> 后，站内绝对链接缺失数为 0。</li><li><code>git diff --check</code> 通过。</li><li>本轮没有运行 VitePress 构建；项目既有 <code>imports</code> 构建问题仍与本轮内容补强分开处理。</li></ul><h2 id="五、仍需保留的边界" tabindex="-1">五、仍需保留的边界 <a class="header-anchor" href="#五、仍需保留的边界" aria-label="Permalink to &quot;五、仍需保留的边界&quot;">​</a></h2><p>本轮补强的是零基础知识解释和判断框架，不把课程中的通用流程写成全国统一评分表。动作时间、压力/流量、照度、声级、允许误差、抽检比例、具体按钮菜单、部件匹配和地方考试口径，仍须以适用标准、设计文件、检测方案、设备说明书、鉴定站公告和当批次评分要求核验。</p>',15)])])}const p=i(d,[["render",t]]);export{m as __pageData,p as default};
